import base64, os, pathlib, subprocess, sys

# Step out of a possibly-deleted previous tree before removing it.
os.chdir("/content")

REPO = "/content/SpMVBench"
BASE = "e32e0c39b45d71f74527142978c1b6533625f167"
PATCH_B64 = """

"""


def sh(cmd, check=True):
    print("\n" + "=" * 78 + "\n$ " + cmd + "\n" + "=" * 78, flush=True)
    LOG.write("\n" + "=" * 78 + "\n$ " + cmd + "\n" + "=" * 78 + "\n")
    LOG.flush()
    p = subprocess.Popen(cmd, shell=True, cwd=REPO, text=True,
                         stdout=subprocess.PIPE, stderr=subprocess.STDOUT)
    for line in p.stdout:
        print(line, end="", flush=True)
        LOG.write(line)
        LOG.flush()
    rc = p.wait()
    LOG.write("\n(exit %d)\n" % rc)
    LOG.flush()
    print("\n(exit %d)" % rc, flush=True)
    if check and rc != 0:
        raise SystemExit("COMMAND FAILED: " + cmd)
    return rc


# Fresh tree at the public base commit + methodology patch.
if os.path.isdir(REPO):
    subprocess.run(["rm", "-rf", REPO], check=True)
subprocess.run(["git", "clone", "--quiet",
                "https://github.com/AbhiramCommits/SpMVBench.git", REPO],
               check=True)
os.chdir(REPO)
subprocess.run(["git", "checkout", "--quiet", "--force", BASE], check=True)
pathlib.Path("/tmp/spmvbench_method.patch").write_bytes(
    base64.b64decode(PATCH_B64))
rc = subprocess.run(["git", "apply", "--whitespace=nowarn",
                     "/tmp/spmvbench_method.patch"]).returncode
print("git apply exit code:", rc)
if rc != 0:
    raise SystemExit("PATCH FAILED TO APPLY")

LOG = open("/content/spmvbench_run.log", "w")

sh("uname -a")
sh("nvidia-smi")
sh("nvcc --version")
sh("nvidia-smi --query-gpu=name,driver_version,memory.total,compute_cap "
   "--format=csv")
sh("nproc")

cc = None
try:
    out = subprocess.check_output(
        ["nvidia-smi", "--query-gpu=compute_cap", "--format=csv,noheader"],
        text=True).strip().splitlines()[0].strip()
    if out and "N/A" not in out and "." in out:
        cc = out.replace(".", "")
except Exception as exc:
    print("compute_cap query failed:", exc)
if cc is None:
    try:
        import torch
        major, minor = torch.cuda.get_device_capability()
        cc = f"{major}{minor}"
    except Exception as exc:
        print("torch fallback failed:", exc)
if cc is None:
    raise SystemExit("Could not determine compute capability")
print("\n>>> CMAKE_CUDA_ARCHITECTURES =", cc, flush=True)

sh("python3 tools/gen_matrices.py --suitesparse-set")
sh("python3 tools/reference.py")
sh("cmake -S . -B build -DSPMVBENCH_ENABLE_CUDA=ON "
   "-DCMAKE_CUDA_ARCHITECTURES=" + cc + " -DCMAKE_BUILD_TYPE=Release")
sh("cmake --build build -j")
sh("ctest --test-dir build --output-on-failure")
sh("./build/bench --validate")
sh("./build/bench --bench --iters 50")
sh("./build/bench --auto --all")
sh("python3 tools/report.py")
sh("bash scripts/profile.sh", check=False)
sh("ls -la results")
sh("tar czf /content/spmvbench_results.tgz results "
   "/content/spmvbench_run.log")
print("RESULTS TAR READY", flush=True)

from google.colab import files
files.download("/content/spmvbench_results.tgz")
print("DONE", flush=True)
